const cfg = $('Config').first().json;
const DAY = 864e5;
const today = new Date(new Date().toISOString().slice(0, 10));
const stageFor = d => d >= 30 ? 'final_30' : d >= 14 ? 'overdue_14' : d >= 7 ? 'overdue_7' : d >= 0 ? 'due' : d >= -3 ? 'pre_due' : null;
const rank = { pre_due: 1, due: 2, overdue_7: 3, overdue_14: 4, final_30: 5 };
const money = (a, c) => { try { return new Intl.NumberFormat('en', { style: 'currency', currency: c || 'USD' }).format(Number(a)); } catch { return `${a} ${c || ''}`; } };
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.invoice_id || !r.client_email || !r.due_date) continue;
  if (['paid', 'void', 'disputed', 'paused'].includes(String(r.status || '').toLowerCase())) continue;
  const days = Math.round((today - new Date(String(r.due_date).slice(0, 10))) / DAY);
  const stage = stageFor(days);
  if (!stage) continue;
  if ((rank[r.last_reminder_stage] || 0) >= rank[stage]) continue; // never repeat or go backwards
  const amt = money(r.amount, r.currency);
  const first = String(r.client_name || '').split(' ')[0] || 'there';
  const link = r.pay_link ? `\nPay online: ${r.pay_link}\n` : '';
  const sig = `\n\nThanks,\n${cfg.ownerName}\n${cfg.businessName}`;
  const T = {
    pre_due: [`Upcoming: invoice ${r.invoice_id} due ${r.due_date}`,
      `Hi ${first},\n\nFriendly heads-up that invoice ${r.invoice_id} for ${amt} is due on ${r.due_date}.\n${link}\n${cfg.paymentDetails}\n\nIf it's already scheduled, please ignore this.`],
    due: [days === 0 ? `Invoice ${r.invoice_id} is due today` : `Reminder: invoice ${r.invoice_id} was due ${r.due_date}`,
      `Hi ${first},\n\nJust a reminder that invoice ${r.invoice_id} (${amt}) ${days === 0 ? 'is due today' : 'was due on ' + r.due_date}.\n${link}\n${cfg.paymentDetails}`],
    overdue_7: [`Invoice ${r.invoice_id} — 1 week overdue`,
      `Hi ${first},\n\nI couldn't see payment for invoice ${r.invoice_id} (${amt}), which was due on ${r.due_date}. Could you check on it, or let me know if anything is holding it up?\n${link}\n${cfg.paymentDetails}`],
    overdue_14: [`Second notice: invoice ${r.invoice_id} (${amt}) overdue`,
      `Hi ${first},\n\nInvoice ${r.invoice_id} for ${amt} is now ${days} days overdue. Please arrange payment this week, or reply with an expected payment date so I can update our records.\n${link}\n${cfg.paymentDetails}`],
    final_30: [`Final notice: invoice ${r.invoice_id} — ${days} days overdue`,
      `Hi ${first},\n\nThis is a final reminder that invoice ${r.invoice_id} for ${amt} is ${days} days overdue. Please settle it within 7 days. ${cfg.lateFeeNote}\n${link}\n${cfg.paymentDetails}\n\nIf there's an issue with the invoice, reply and I'll sort it out right away.`],
  }[stage];
  out.push({ json: { ...r, days_overdue: days, stage, amount_fmt: amt, subject: T[0], body: T[1] + sig } });
}
return out;

const rows = $('Pick Reminder Stage').all().map(i => i.json);
const finals = rows.filter(r => r.stage === 'final_30');
const lines = rows.map(r => `• ${r.invoice_id}  ${r.client_name}  ${r.amount_fmt}  → ${r.stage} (${r.days_overdue}d)`);
return [{ json: {
  subject: `💸 ${rows.length} payment reminder(s) sent${finals.length ? ` — ${finals.length} FINAL notice(s), call them` : ''}`,
  body: `Reminders sent today:\n\n${lines.join('\n')}\n\n${finals.length ? 'Final notices went to: ' + finals.map(f => f.client_name + ' <' + f.client_email + '>').join(', ') + '\nA phone call usually works better than another email now.' : ''}`,
}}];
